DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `Email` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Password` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Fullname` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Gender` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `IsDeleted` tinyint DEFAULT '0',
  `CreatedAt` datetime(3) DEFAULT CURRENT_TIMESTAMP(3),
  `CreatedBy` int DEFAULT NULL,
  `Avatar` longtext COLLATE utf8mb4_general_ci,
  `ChangeHistory` longtext COLLATE utf8mb4_general_ci,
  `Location` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `Email` (`Email`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
